1	// Single place to import gsap from. Plugins are registered exactly once,
2	// guarded against SSR — gsap must never run on the server.
3	//
4	// Always import from here, never directly from 'gsap', so plugins are
5	// guaranteed to be registered before use.
6	
7	import { gsap } from 'gsap';
8	import { ScrollTrigger } from 'gsap/ScrollTrigger';
9	
10	if (typeof window !== 'undefined') {
11	  gsap.registerPlugin(ScrollTrigger);
12	}
13	
14	/**
15	 * Honors the user's OS-level "reduce motion" preference. Components
16	 * that run reveal / stagger animations should bail out early when
17	 * this returns true. Always returns false on the server (no signal
18	 * available) so SSR markup matches the un-animated final state.
19	 */
20	export function prefersReducedMotion(): boolean {
21	  if (typeof window === 'undefined') return false;
22	  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
23	}
24	
25	export { gsap, ScrollTrigger };
26	export { useGSAP } from '@gsap/react';
27

1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	import type { ContentType } from "@/types";
5	import { getReadingPosition } from "./api";
6	import { getSessionToken } from "./session";
7	
8	const API_URL =
9	  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001/api";
10	
11	/** Minimum time between scroll-driven position writes. */
12	const WRITE_THROTTLE_MS = 5000;
13	
14	/**
15	 * Anything below this percentage is the visitor effectively "at the
16	 * top." Skip the restore so a 2% scroll on a long chapter doesn't
17	 * jolt back to where their finger barely touched.
18	 */
19	const RESTORE_MIN_PERCENT = 4;
20	
21	/**
22	 * Same idea at the top of the document: don't write a scroll
23	 * position at < 2% — every "open the chapter and immediately scroll
24	 * a hair" event would otherwise overwrite a real, higher position
25	 * we've already saved.
26	 */
27	const WRITE_MIN_PERCENT = 2;
28	
29	interface Options {
30	  contentType: ContentType;
31	  contentId: string;
32	  /**
33	   * Current page in paged-mode chapters. Stored alongside the
34	   * scroll percentage so resume lands the reader on the right page
35	   * before scrolling. Pass null in infinite-mode.
36	   */
37	  pageNumber: number | null;
38	  /**
39	   * True when there's content rendered + the page can scroll.
40	   * Used to gate the restore-on-mount until the article has paint
41	   * — restoring against an empty document would scroll nowhere.
42	   */
43	  enabled?: boolean;
44	}
45	
46	/**
47	 * Tracks the reader's vertical position within the article and
48	 * restores it on the next visit. Pairs with the backend
49	 * `/api/reading-positions` endpoints.
50	 *
51	 * Lifecycle:
52	 *   1. On mount (or when contentId / pageNumber changes) fetch any
53	 *      stored position. If it matches the current pageNumber and is
54	 *      ≥ RESTORE_MIN_PERCENT, schedule a scroll via
55	 *      requestIdleCallback so it happens after first paint without
56	 *      racing layout.
57	 *   2. While the user scrolls, throttle a `sendBeacon` write to
58	 *      `/api/reading-positions` every WRITE_THROTTLE_MS so we don't
59	 *      hammer the backend.
60	 *   3. On `visibilitychange → hidden` and `pagehide` flush the
61	 *      latest position so a tab close doesn't lose the most recent
62	 *      few seconds of scrolling.
63	 *
64	 * Idempotent at the API layer: a duplicate write for the same
65	 * (contentType, contentId, identifier) upserts onto the existing
66	 * row, so firing twice on a flaky exit is a no-op.
67	 */
68	export function useReadingPosition({
69	  contentType,
70	  contentId,
71	  pageNumber,
72	  enabled = true,
73	}: Options) {
74	  // Hold the latest "should we still be running" flag in a ref so
75	  // the cleanup paths can short-circuit without going through the
76	  // closure's value (which is captured at effect-fire time).
77	  const enabledRef = useRef(enabled);
78	  enabledRef.current = enabled;
79	
80	  // Track the last write so we can throttle by elapsed time without
81	  // a setInterval — `setTimeout` chains lose timing accuracy fast.
82	  const lastWriteAtRef = useRef(0);
83	  const pendingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(
84	    null,
85	  );
86	
87	  useEffect(() => {
88	    if (!enabled) return;
89	    if (typeof window === "undefined") return;
90	
91	    let cancelled = false;
92	
93	    // ── Restore on mount ────────────────────────────────────────
94	    //
95	    // Wrap in idle-callback so the article has time to lay out
96	    // before we try to scrollTo. Without this, the percentage maps
97	    // to "0" because document.documentElement.scrollHeight is still
98	    // the viewport height during hydration.
99	    const sessionToken = getSessionToken();
100	    void (async () => {
101	      try {
102	        const pos = await getReadingPosition(contentType, contentId, sessionToken);
103	        if (cancelled || !pos) return;
104	        // Skip restore if the stored position is on a different
105	        // page (paged mode) — the page-aware URL handling in the
106	        // ReadingView will get the visitor onto the right page;
107	        // then the hook re-fires with the new pageNumber and the
108	        // restore matches.
109	        if (pos.pageNumber !== pageNumber) return;
110	        if (pos.scrollPercentage < RESTORE_MIN_PERCENT) return;
111	
112	        const restore = () => {
113	          if (cancelled) return;
114	          const doc = document.documentElement;
115	          const target =
116	            (pos.scrollPercentage / 100) *
117	            (doc.scrollHeight - window.innerHeight);
118	          if (!Number.isFinite(target) || target <= 0) return;
119	          window.scrollTo({ top: target, behavior: "instant" });
120	        };
121	        // `requestIdleCallback` falls back to rAF on Safari — that
122	        // still gets us past the synchronous hydration tick.
123	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
124	        const ric = (window as any).requestIdleCallback as
125	          | undefined
126	          | ((cb: () => void, opts?: { timeout: number }) => number);
127	        if (typeof ric === "function") {
128	          ric(restore, { timeout: 500 });
129	        } else {
130	          requestAnimationFrame(restore);
131	        }
132	      } catch {
133	        // Network failure / bad response — leave the user at the
134	        // top. The next scroll will start writing a fresh position.
135	      }
136	    })();
137	
138	    // ── Write throttler ─────────────────────────────────────────
139	
140	    const buildBody = () => {
141	      const doc = document.documentElement;
142	      const denom = doc.scrollHeight - window.innerHeight;
143	      const pct = denom > 0 ? (window.scrollY / denom) * 100 : 0;
144	      const clamped = Math.max(0, Math.min(100, pct));
145	      return {
146	        contentType,
147	        contentId,
148	        scrollPercentage: clamped,
149	        pageNumber,
150	        sessionToken,
151	      };
152	    };
153	
154	    const sendNow = () => {
155	      const body = buildBody();
156	      if (body.scrollPercentage < WRITE_MIN_PERCENT) return;
157	      lastWriteAtRef.current = Date.now();
158	      try {
159	        navigator.sendBeacon(
160	          `${API_URL}/reading-positions`,
161	          new Blob([JSON.stringify(body)], { type: "application/json" }),
162	        );
163	      } catch {
164	        // sendBeacon throws synchronously on payload-too-large /
165	        // wrong type. Should never happen for our payload size,
166	        // but a swallow keeps the hook resilient.
167	      }
168	    };
169	
170	    const flushPending = () => {
171	      if (pendingTimeoutRef.current) {
172	        clearTimeout(pendingTimeoutRef.current);
173	        pendingTimeoutRef.current = null;
174	      }
175	      sendNow();
176	    };
177	
178	    const onScroll = () => {
179	      const elapsed = Date.now() - lastWriteAtRef.current;
180	      if (elapsed >= WRITE_THROTTLE_MS) {
181	        sendNow();
182	        return;
183	      }
184	      // Schedule a trailing flush so we capture the user's final
185	      // resting position even if they stop scrolling between throttle
186	      // windows.
187	      if (pendingTimeoutRef.current) return;
188	      pendingTimeoutRef.current = setTimeout(() => {
189	        pendingTimeoutRef.current = null;
190	        sendNow();
191	      }, WRITE_THROTTLE_MS - elapsed);
192	    };
193	
194	    const onVisibility = () => {
195	      if (document.visibilityState === "hidden") flushPending();
196	    };
197	
198	    window.addEventListener("scroll", onScroll, { passive: true });
199	    document.addEventListener("visibilitychange", onVisibility);
200	    window.addEventListener("pagehide", flushPending);
201	
202	    return () => {
203	      cancelled = true;
204	      window.removeEventListener("scroll", onScroll);
205	      document.removeEventListener("visibilitychange", onVisibility);
206	      window.removeEventListener("pagehide", flushPending);
207	      if (pendingTimeoutRef.current) {
208	        clearTimeout(pendingTimeoutRef.current);
209	        pendingTimeoutRef.current = null;
210	      }
211	      // Flush one final write on unmount (SPA route change) so the
212	      // user's last position before navigating away is captured.
213	      flushPending();
214	    };
215	  }, [contentType, contentId, pageNumber, enabled]);
216	}
