1	/* One note in the admin NotesPanel.
2	   The data-color attribute on .card maps to --note-color so the dot
3	   and accents pick up the right tone automatically.
4	
5	   Palette tuned for the dark canvas — muted, dim-glow, literary. */
6	
7	.card {
8	  --note-color: var(--gold);
9	  position: relative;
10	  display: flex;
11	  flex-direction: column;
12	  background: var(--bg-surface);
13	  border: 1px solid var(--border-line);
14	  border-radius: var(--radius-md-app);
15	  font-family: var(--font-ui);
16	  /* Per-property transitions so hover/active/swap each feel right
17	     instead of one blanket ease that drags everything along. */
18	  transition:
19	    border-color var(--transition-fast),
20	    transform 180ms cubic-bezier(0.16, 1, 0.3, 1),
21	    box-shadow 220ms cubic-bezier(0.16, 1, 0.3, 1);
22	}
23	
24	.card[data-color="GOLD"]    { --note-color: var(--gold); }
25	.card[data-color="CRIMSON"] { --note-color: #c4584c; }
26	.card[data-color="SAGE"]    { --note-color: #7fa17b; }
27	.card[data-color="INDIGO"]  { --note-color: #7e8ed1; }
28	.card[data-color="AMBER"]   { --note-color: #d99a4a; }
29	.card[data-color="SLATE"]   { --note-color: #8a8e97; }
30	
31	/* ── Collapsed pill ────────────────────────────────────────────── */
32	.collapsed {
33	  flex-direction: row;
34	  align-items: center;
35	  gap: 4px;
36	  padding: 4px 6px 4px 12px;
37	  border-radius: var(--radius-pill);
38	}
39	.collapsed:hover {
40	  border-color: var(--note-color);
41	  /* Small lift + soft glow keyed to the note's color — feels alive
42	     under the cursor without being noisy. */
43	  transform: translateY(-1px);
44	  box-shadow: 0 6px 14px -8px color-mix(in srgb, var(--note-color) 55%, transparent);
45	}
46	.collapsed:active {
47	  transform: translateY(0) scale(0.995);
48	  box-shadow: none;
49	}
50	
51	.pillBody {
52	  display: inline-flex;
53	  align-items: center;
54	  gap: 10px;
55	  flex: 1 1 auto;
56	  min-width: 0;
57	  background: transparent;
58	  border: 0;
59	  padding: 6px 0;
60	  font: inherit;
61	  color: var(--text);
62	  cursor: pointer;
63	  text-align: left;
64	}
65	.pillBody:focus-visible {
66	  outline: 2px solid var(--gold);
67	  outline-offset: 2px;
68	  border-radius: var(--radius-pill);
69	}
70	
71	.dot {
72	  flex: 0 0 auto;
73	  width: 10px;
74	  height: 10px;
75	  border-radius: 50%;
76	  background: var(--note-color);
77	  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35) inset;
78	}
79	
80	.pillTitle {
81	  flex: 1 1 auto;
82	  min-width: 0;
83	  font-size: 13px;
84	  font-weight: 500;
85	  letter-spacing: 0.01em;
86	  color: var(--text);
87	  overflow: hidden;
88	  text-overflow: ellipsis;
89	  white-space: nowrap;
90	}
91	
92	/* ── Expanded card ─────────────────────────────────────────────── */
93	.expanded {
94	  padding: 10px 10px 12px;
95	  border-color: var(--note-color);
96	  /* Stretch to consume any remaining vertical space in the panel's
97	     list — the textarea inside grows with it. Collapsed pill
98	     siblings stay at intrinsic height. */
99	  flex: 1 1 auto;
100	  display: flex;
101	  flex-direction: column;
102	  min-height: 220px;
103	  /* Tiny fade + lift-in on mount — runs on pill→expanded swap and
104	     when a brand-new note is added (it spawns expanded). Subtle, so
105	     it never reads as decoration. */
106	  animation: noteExpandIn 200ms cubic-bezier(0.16, 1, 0.3, 1) both;
107	}
108	
109	@keyframes noteExpandIn {
110	  from {
111	    opacity: 0.4;
112	    transform: translateY(-3px);
113	  }
114	  to {
115	    opacity: 1;
116	    transform: translateY(0);
117	  }
118	}
119	
120	.expandedHeader {
121	  display: flex;
122	  align-items: center;
123	  gap: 6px;
124	  margin-bottom: 8px;
125	}
126	
127	.collapseBtn {
128	  display: inline-flex;
129	  align-items: center;
130	  justify-content: center;
131	  width: 26px;
132	  height: 26px;
133	  background: transparent;
134	  border: 0;
135	  border-radius: var(--radius-pill);
136	  cursor: pointer;
137	  padding: 0;
138	  color: var(--text-muted);
139	  transition: background var(--transition-fast);
140	}
141	.collapseBtn:hover {
142	  background: var(--bg);
143	}
144	.collapseBtn:focus-visible {
145	  outline: 2px solid var(--gold);
146	  outline-offset: 2px;
147	}
148	
149	.titleInput {
150	  flex: 1 1 auto;
151	  min-width: 0;
152	  background: transparent;
153	  border: 0;
154	  border-bottom: 1px solid transparent;
155	  padding: 4px 2px;
156	  font-family: var(--font-display);
157	  font-size: 15px;
158	  font-weight: 600;
159	  color: var(--text);
