170	}
171	
172	.bodyArea {
173	  width: 100%;
174	  /* Flex-grow inside the expanded card so the textarea fills the
175	     panel's vertical space. The min-height keeps the textarea
176	     usable even when the panel is short (collapsed neighbours
177	     above eating the space). resize:none avoids fighting the
178	     flex sizing with a manual handle. */
179	  flex: 1 1 auto;
180	  min-height: 140px;
181	  resize: none;
182	  background: var(--bg);
183	  border: 1px solid var(--border-line);
