185	  padding: 10px 12px;
186	  font-family: var(--font-reading);
187	  font-size: 14px;
188	  line-height: 1.55;
189	  color: var(--text);
190	  outline: none;
191	  transition: border-color var(--transition-fast);
192	}
193	.bodyArea::placeholder {
194	  color: var(--text-muted);
195	  font-style: italic;
196	}
197	.bodyArea:focus {
198	  border-color: var(--note-color);
199	}
200	
201	/* ── 3-dot action menu ─────────────────────────────────────────── */
202	.menuWrap {
203	  position: relative;
204	  flex: 0 0 auto;
205	}
206	
207	.menuBtn {
208	  display: inline-flex;
209	  align-items: center;
210	  justify-content: center;
211	  width: 28px;
212	  height: 28px;
213	  background: transparent;
214	  border: 0;
215	  border-radius: var(--radius-pill);
216	  cursor: pointer;
217	  padding: 0;
218	  color: var(--text-muted);
219	  transition: background var(--transition-fast), color var(--transition-fast);
220	}
221	.menuBtn:hover {
222	  background: var(--bg);
223	  color: var(--text);
224	}
225	.menuBtn:focus-visible {
226	  outline: 2px solid var(--gold);
227	  outline-offset: 2px;
228	}
229	
230	.menuPanel {
231	  position: absolute;
232	  top: calc(100% + 6px);
233	  right: 0;
234	  z-index: 50;
235	  display: flex;
236	  flex-direction: column;
237	  gap: 8px;
238	  min-width: 180px;
239	  padding: 10px 12px;
240	  background: var(--bg-surface);
241	  border: 1px solid var(--border-line);
242	  border-radius: var(--radius-md-app);
243	  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.7);
244	  /* Pop-in from the top-right (where the 3-dot trigger sits) so the
245	     spatial origin reads correctly. */
246	  transform-origin: top right;
247	  animation: menuPop 160ms cubic-bezier(0.16, 1, 0.3, 1) both;
248	}
249	
250	@keyframes menuPop {
251	  from {
252	    opacity: 0;
253	    transform: translateY(-4px) scale(0.96);
254	  }
255	  to {
256	    opacity: 1;
257	    transform: translateY(0) scale(1);
258	  }
259	}
260	
261	.menuLabel {
262	  margin: 0;
263	  font-family: var(--font-ui);
264	  font-size: 11px;
265	  font-weight: 600;
266	  letter-spacing: 0.16em;
267	  text-transform: uppercase;
268	  color: var(--text-muted);
269	}
