271	.swatchRow {
272	  display: grid;
273	  grid-template-columns: repeat(6, 1fr);
274	  gap: 6px;
275	}
276	
277	.swatch {
278	  width: 22px;
279	  height: 22px;
280	  border-radius: 50%;
281	  border: 2px solid transparent;
282	  cursor: pointer;
283	  padding: 0;
284	  display: inline-flex;
285	  align-items: center;
286	  justify-content: center;
287	  color: rgba(0, 0, 0, 0.85);
288	  transition: transform var(--transition-fast), border-color var(--transition-fast);
289	}
290	.swatch[data-color="GOLD"]    { background: var(--gold); }
291	.swatch[data-color="CRIMSON"] { background: #c4584c; }
292	.swatch[data-color="SAGE"]    { background: #7fa17b; }
293	.swatch[data-color="INDIGO"]  { background: #7e8ed1; }
294	.swatch[data-color="AMBER"]   { background: #d99a4a; }
295	.swatch[data-color="SLATE"]   { background: #8a8e97; }
296	.swatch:hover {
297	  transform: scale(1.08);
298	}
299	.swatch:focus-visible {
300	  outline: 2px solid var(--gold);
301	  outline-offset: 2px;
302	}
303	.swatchActive {
304	  border-color: var(--text);
305	}
306	
307	.deleteBtn {
308	  background: transparent;
309	  border: 1px solid var(--border-line);
310	  border-radius: var(--radius-md-app);
311	  padding: 7px 10px;
312	  font-family: var(--font-ui);
313	  font-size: 12px;
314	  font-weight: 500;
315	  letter-spacing: 0.04em;
316	  color: var(--like);
317	  cursor: pointer;
318	  text-align: left;
319	  transition: background var(--transition-fast), border-color var(--transition-fast);
320	}
321	.deleteBtn:hover {
322	  background: var(--bg);
323	  border-color: var(--like);
324	}
325	.deleteBtn:focus-visible {
326	  outline: 2px solid var(--like);
327	  outline-offset: 2px;
328	}
