330	/* Respect the OS-level "Reduce Motion" preference — keep the visual
331	   states but drop the motion. The codebase already honors this in
332	   the GSAP morphs in SiteHeader; mirror that here. */
333	@media (prefers-reduced-motion: reduce) {
334	  .card,
335	  .collapsed,
336	  .expanded,
337	  .menuPanel,
338	  .collapseBtn,
339	  .menuBtn,
340	  .swatch {
341	    animation: none !important;
342	    transition: none !important;
343	  }
