1	/* Persistent right-column notes panel on the admin editor.
2	
3	   Wide screens (>=1100px): inline in the page grid, sticky so it
4	     stays visible while the writer scrolls a long body.
5	   Narrow screens (<1100px): hidden by default; revealed as a
6	     slide-in sheet from the right when the FAB is tapped. */
7	
8	.panel {
9	  display: flex;
10	  flex-direction: column;
11	  gap: 12px;
12	  align-self: start;
13	  /* Wider than the original 340px so the panel absorbs the empty
14	     space between ContentForm's 1200px max-width and the right
15	     viewport edge on standard desktop widths. */
16	  width: clamp(360px, 32vw, 600px);
17	  max-height: calc(100dvh - 96px);
18	  padding: 14px;
19	  background: var(--bg-surface);
20	  border: 1px solid var(--border-line);
21	  border-radius: var(--radius-md-app);
22	  position: sticky;
23	  top: 24px;
24	  font-family: var(--font-ui);
25	  /* Silky expand/collapse — ease-out-quart is the curve that reads
26	     as "natural deceleration", not "linear lerp". Includes
27	     min-height (PR #180 added it) so growth and shrink are paired. */
28	  transition:
29	    max-height 260ms cubic-bezier(0.16, 1, 0.3, 1),
30	    min-height 260ms cubic-bezier(0.16, 1, 0.3, 1),
31	    top 260ms cubic-bezier(0.16, 1, 0.3, 1);
32	}
33	
34	/* When any note inside is expanded, anchor the panel just below the
35	   sticky admin top bar (~66px) and stretch it to the bottom of the
36	   viewport — the whole right column becomes a writing surface, with
37	   the expanded note's textarea flex-filling the available space. */
38	.panel.hasExpanded {
39	  top: 76px;
40	  /* min-height makes the panel actually grow to the floor, not just
41	     allow it. Without it, the panel was sized to its content (a
42	     handful of pills) and the "max" never bound. */
43	  min-height: calc(100dvh - 90px);
44	  max-height: calc(100dvh - 90px);
45	}
46	
47	.header {
48	  display: flex;
49	  align-items: center;
50	  justify-content: space-between;
51	  gap: 8px;
52	  padding-bottom: 8px;
53	  border-bottom: 1px solid var(--border-line);
54	}
55	
56	.title {
57	  margin: 0;
58	  font-family: var(--font-display);
59	  font-size: 16px;
60	  font-weight: 600;
61	  letter-spacing: 0.02em;
62	  color: var(--text);
63	}
64	
65	.list {
66	  display: flex;
67	  flex-direction: column;
68	  gap: 8px;
69	  flex: 1 1 auto;
70	  /* min-height: 0 lets the expanded NoteCard inside actually shrink
71	     below its content's intrinsic height — without it, flex-grow on
72	     the card wouldn't be able to constrain the textarea. */
73	  min-height: 0;
74	  overflow-y: auto;
75	  /* Breathing room so the bottom card isn't flush against the
76	     "Add note" button. */
77	  padding: 4px 0 4px;
78	}
79	
80	.empty {
81	  margin: 16px 0;
82	  text-align: center;
83	  font-style: italic;
84	  font-size: 13px;
85	  color: var(--text-muted);
86	}
87	
88	.error {
89	  margin: 0;
90	  padding: 8px 10px;
91	  background: rgba(196, 88, 76, 0.08);
92	  border: 1px solid rgba(196, 88, 76, 0.35);
93	  border-radius: var(--radius-md-app);
94	  font-size: 12px;
95	  color: var(--like);
96	}
97	
98	.addBtn {
99	  margin-top: 4px;
100	  padding: 9px 12px;
101	  background: transparent;
102	  border: 1px dashed var(--border-line);
103	  border-radius: var(--radius-md-app);
104	  font-family: var(--font-ui);
105	  font-size: 13px;
106	  font-weight: 500;
107	  color: var(--text-muted);
108	  cursor: pointer;
109	  text-align: center;
110	  transition:
111	    border-color var(--transition-fast),
112	    color var(--transition-fast),
113	    background var(--transition-fast),
114	    transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
115	}
116	.addBtn:hover {
117	  border-color: var(--gold);
118	  color: var(--gold);
119	  /* Tiny lift — the button "comes to meet you" on hover, matches
120	     the brand's other gold-accent CTAs (Start Reading on /). */
121	  transform: translateY(-1px);
122	}
123	.addBtn:active {
124	  transform: translateY(0) scale(0.99);
125	}
126	.addBtn:focus-visible {
127	  outline: 2px solid var(--gold);
128	  outline-offset: 2px;
129	}
130	.addBtn:disabled {
131	  opacity: 0.5;
132	  cursor: not-allowed;
133	  transform: none;
134	}
135	
136	/* ── Mobile-only chrome ─────────────────────────────────────────
137	   The close button, the FAB, and the scrim are hidden on wide
138	   screens. The panel itself becomes a fixed slide-in sheet under
139	   1100px and slides in when `.mobileOpen` is on. */
140	
141	.closeMobile {
142	  display: none;
143	  background: transparent;
144	  border: 0;
145	  width: 32px;
146	  height: 32px;
147	  border-radius: 50%;
148	  cursor: pointer;
149	  color: var(--text-muted);
150	  padding: 0;
151	}
152	.closeMobile:hover {
153	  color: var(--text);
154	  background: var(--bg);
155	}
156	
157	.mobileFab {
158	  display: none; /* desktop hides it */
159	  position: fixed;
160	  right: 18px;
161	  bottom: 18px;
162	  z-index: 80;
163	  align-items: center;
164	  gap: 8px;
165	  padding: 10px 16px;
166	  background: var(--bg-surface);
167	  border: 1px solid var(--gold);
168	  border-radius: var(--radius-pill);
169	  color: var(--gold);
170	  font-family: var(--font-ui);
171	  font-size: 13px;
172	  font-weight: 600;
173	  letter-spacing: 0.06em;
174	  text-transform: uppercase;
175	  box-shadow: 0 12px 28px -10px rgba(0, 0, 0, 0.7);
176	  cursor: pointer;
177	}
178	.mobileFab:focus-visible {
179	  outline: 2px solid var(--gold);
180	  outline-offset: 2px;
181	}
182	
183	.fabBadge {
184	  display: inline-flex;
185	  align-items: center;
186	  justify-content: center;
187	  min-width: 18px;
188	  height: 18px;
189	  padding: 0 5px;
190	  background: var(--gold);
191	  border-radius: 9px;
192	  font-size: 10px;
193	  font-weight: 700;
194	  color: var(--bg);
195	  letter-spacing: 0;
196	}
197	
198	.scrim {
199	  display: none; /* desktop hides it */
200	  position: fixed;
201	  inset: 0;
202	  z-index: 70;
203	  background: rgba(0, 0, 0, 0.55);
204	}
205	
206	@media (max-width: 1100px) {
207	  /* Sheet mode: panel becomes a fixed slide-in from the right. */
208	  .panel {
209	    position: fixed;
210	    inset: 0 0 0 auto;
211	    width: min(360px, 92vw);
212	    max-height: 100dvh;
213	    height: 100dvh;
214	    border-radius: 0;
215	    border-left: 1px solid var(--border-line);
216	    border-right: 0;
217	    border-top: 0;
218	    border-bottom: 0;
219	    z-index: 90;
220	    top: auto;
221	    transform: translateX(100%);
222	    transition: transform 220ms ease-out;
223	  }
224	  .panel.mobileOpen {
225	    transform: translateX(0);
226	  }
227	  .closeMobile {
228	    display: inline-flex;
229	    align-items: center;
230	    justify-content: center;
231	  }
232	  .mobileFab {
233	    display: inline-flex;
234	  }
235	  .scrim {
236	    display: block;
237	  }
238	}
239	
240	/* Reduced-motion: keep the layout, lose the animation. Sheet slide
241	   becomes a snap; panel height changes apply instantly. */
242	@media (prefers-reduced-motion: reduce) {
243	  .panel,
244	  .addBtn,
245	  .mobileFab {
246	    transition: none !important;
247	  }
248	  .addBtn:hover,
249	  .addBtn:active {
250	    transform: none;
