16	export default function LikeButton({ contentType, contentId, initialCount }: Props) {
17	  const buttonRef = useRef<HTMLButtonElement>(null);
18	  const [liked, setLiked] = useState(false);
19	  const [count, setCount] = useState(initialCount);
20	  const [pending, setPending] = useState(false);
21	
22	  // Read the current liked state once on mount.
23	  useEffect(() => {
24	    let cancelled = false;
25	    void (async () => {
26	      try {
27	        const token = getSessionToken();
28	        const { liked } = await getLikeStatus(contentType, contentId, token);
29	        if (!cancelled) setLiked(liked);
30	      } catch {
31	        // Network failure shouldn't block the page.
32	      }
33	    })();
34	    return () => {
35	      cancelled = true;
36	    };
37	  }, [contentType, contentId]);
38	
39	  useGSAP(
40	    () => {
41	      // No-op until pulse() is called below — this scope is just here
42	      // so all gsap.from/to animations are auto-cleaned up.
43	    },
44	    { scope: buttonRef },
45	  );
46	
47	  const pulse = () => {
48	    if (!buttonRef.current) return;
49	    if (prefersReducedMotion()) return;
50	    gsap.fromTo(
51	      buttonRef.current,
52	      { scale: 1 },
53	      { scale: 1.15, duration: 0.1, yoyo: true, repeat: 1, ease: "power2.out" },
54	    );
55	  };
56	
57	  const toggle = async () => {
58	    if (pending) return;
59	    pulse();
60	
61	    // Optimistic update
62	    const wasLiked = liked;
63	    const prevCount = count;
64	    setLiked(!wasLiked);
65	    setCount((c) => c + (wasLiked ? -1 : 1));
66	    setPending(true);
67	
68	    try {
69	      const sessionToken = getSessionToken();
70	      const body = { contentType, contentId, sessionToken };
71	      if (wasLiked) {
72	        await deleteLike(body);
73	      } else {
74	        await postLike(body);
75	      }
76	    } catch {
77	      // Revert on failure.
78	      setLiked(wasLiked);
79	      setCount(prevCount);
80	    } finally {
81	      setPending(false);
82	    }
83	  };
84	
85	  return (
86	    <button
87	      ref={buttonRef}
88	      type="button"
89	      onClick={toggle}
90	      disabled={pending}
91	      aria-pressed={liked}
92	      aria-label={liked ? "Unlike" : "Like"}
93	      className={`${styles.button} ${liked ? styles.liked : ""}`}
94	    >
95	      <Heart filled={liked} />
96	      <span className={styles.count}>{count}</span>
97	    </button>
98	  );
99	}
