18	}
19	
20	/**
21	 * Bookmark control. Logged-in users save / unsave server-side; the
22	 * dashboard reads the list back. Anonymous users see a disabled
23	 * variant that points at /signup with a helpful tooltip — we don't
24	 * silently swallow taps.
25	 */
26	export default function SaveButton({ contentType, contentId }: Props) {
27	  const auth = useAuth();
28	  const [saved, setSaved] = useState(false);
29	  const [pending, setPending] = useState(false);
30	  const [hydrated, setHydrated] = useState(false);
31	
32	  // Hydrate "is this saved" from the server once we know we're
33	  // logged in. Anonymous users never hit the network here.
34	  useEffect(() => {
35	    if (auth.status !== "authenticated") {
36	      setHydrated(false);
37	      return;
38	    }
39	    let cancelled = false;
40	    void (async () => {
41	      try {
42	        const { saved } = await getSaveStatus(contentType, contentId);
43	        if (!cancelled) {
44	          setSaved(saved);
45	          setHydrated(true);
46	        }
47	      } catch {
48	        // Network failure shouldn't block the UI.
49	        if (!cancelled) setHydrated(true);
50	      }
51	    })();
52	    return () => {
53	      cancelled = true;
54	    };
55	  }, [auth.status, contentType, contentId]);
56	
57	  // Anonymous: render a "Sign up to save" link.
58	  if (auth.status !== "authenticated") {
59	    return (
60	      <Link
61	        href="/signup"
62	        className={styles.button}
63	        title="Sign up to save stories"
64	        aria-label="Sign up to save stories"
65	      >
66	        <BookmarkIcon filled={false} />
67	        <span>Save</span>
68	      </Link>
69	    );
70	  }
71	
72	  const toggle = async () => {
73	    if (pending) return;
74	    const wasSaved = saved;
75	    setSaved(!wasSaved);
76	    setPending(true);
77	    try {
78	      if (wasSaved) {
79	        await deleteSave(contentType, contentId);
80	      } else {
81	        await postSave(contentType, contentId);
82	      }
83	    } catch (err) {
84	      // Roll back on failure. A 409 from postSave means the row was
85	      // already there (probably from a double-tap) — treat as success.
86	      if (err instanceof UserApiError && err.status === 409 && !wasSaved) {
87	        // No-op — server agrees it's saved.
88	      } else {
89	        setSaved(wasSaved);
90	      }
91	    } finally {
92	      setPending(false);
93	    }
94	  };
95	
96	  return (
97	    <button
98	      type="button"
99	      onClick={() => void toggle()}
100	      disabled={pending || !hydrated}
101	      aria-pressed={saved}
102	      aria-label={saved ? "Remove from saved" : "Save"}
103	      className={`${styles.button} ${saved ? styles.saved : ""}`}
104	    >
105	      <BookmarkIcon filled={saved} />
106	      <span>{saved ? "Saved" : "Save"}</span>
107	    </button>
108	  );
109	}
