113	    <svg
114	      className={styles.icon}
115	      viewBox="0 0 24 24"
116	      stroke="currentColor"
117	      fill={filled ? "currentColor" : "none"}
118	      strokeWidth="1.75"
119	      strokeLinecap="round"
120	      strokeLinejoin="round"
121	      aria-hidden="true"
122	      suppressHydrationWarning
123	    >
124	      <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z" />
125	    </svg>
126	  );
127	}
