4	import { useEffect, useMemo, useRef, useState } from "react";
5	import type { Tag } from "@/types";
6	import styles from "./TagBar.module.css";
7	
8	/**
9	 * Tracks which edges of the horizontal-scroll tag row have content
10	 * past them, so the CSS can fade the appropriate edge(s). Returns
11	 * "none" when the row fits without scrolling, and "start" / "middle"
12	 * / "end" when it overflows — start = at the leftmost position
13	 * (only right edge has more), middle = both, end = scrolled to the
14	 * end (only left edge has more).
15	 */
16	function useScrollEdges(ref: React.RefObject<HTMLDivElement | null>) {
17	  const [edge, setEdge] = useState<"none" | "start" | "middle" | "end">("start");
18	
19	  useEffect(() => {
20	    const el = ref.current;
21	    if (!el) return;
22	
23	    const update = () => {
24	      // Re-read from the ref each call rather than relying solely on
25	      // the captured `el`. If the DOM element is detached between
26	      // listener registration and the next event, this stays safe
27	      // instead of dereferencing a node that's no longer in the tree.
28	      const current = ref.current;
29	      if (!current) return;
30	      // 1-px tolerance for sub-pixel scroll positions.
31	      if (current.scrollWidth <= current.clientWidth + 1) {
32	        setEdge("none");
33	        return;
34	      }
35	      const atStart = current.scrollLeft <= 1;
36	      const atEnd =
37	        current.scrollLeft + current.clientWidth >= current.scrollWidth - 1;
38	      if (atStart) setEdge("start");
39	      else if (atEnd) setEdge("end");
40	      else setEdge("middle");
41	    };
42	
43	    update();
44	    el.addEventListener("scroll", update, { passive: true });
45	    // Resize can change whether the row overflows at all.
46	    window.addEventListener("resize", update);
47	    return () => {
48	      el.removeEventListener("scroll", update);
49	      window.removeEventListener("resize", update);
50	    };
51	  }, [ref]);
52	
53	  return edge;
54	}
