191	function CollapsedRow({
192	  sortedTags,
193	  allHref,
194	  activeSet,
195	  buildTagHref,
196	  showToggle,
197	  onExpand,
198	}: {
199	  sortedTags: Tag[];
200	  allHref: string;
201	  activeSet: Set<string>;
202	  buildTagHref: (id: string) => string;
203	  showToggle: boolean;
