1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import {
5	  deleteReadingPosition,
6	  getContinueReading,
7	  type ContinueReadingItem,
8	} from "@/lib/api";
9	import { getSessionToken } from "@/lib/session";
10	import ContinueCard from "./ContinueCard";
11	import styles from "./ContinueReadingRow.module.css";
12	
13	/**
14	 * Homepage row showing the reader's most-recent reading positions
15	 * fetched from the backend. Distinct from the localStorage-backed
16	 * `ContinueReadingRow` (which tracks last-opened chapter per series
17	 * and stays for offline / anonymous use); this row needs scroll-
18	 * percentage data, which only the backend has.
19	 *
20	 * Client component so it can:
21	 *   - Read the anonymous sessionToken from localStorage to identify
22	 *     anonymous callers (matches the likes / saves API contract).
23	 *   - Drive the optimistic remove flow without a server round trip
24	 *     to update the rendered list.
25	 *
26	 * Renders nothing on the server + first paint — the row only
27	 * appears once the fetch resolves, so first-time visitors see the
28	 * regular feed straight away.
29	 */
30	export default function ResumeReadingRow() {
31	  const [items, setItems] = useState<ContinueReadingItem[] | null>(null);
32	
33	  useEffect(() => {
34	    let cancelled = false;
35	    void (async () => {
36	      try {
37	        const sessionToken = getSessionToken();
38	        const list = await getContinueReading(sessionToken);
39	        if (!cancelled) setItems(list);
40	      } catch {
41	        // Backend down or 4xx — silently render nothing rather than
42	        // erroring the whole homepage on a non-critical surface.
43	        if (!cancelled) setItems([]);
44	      }
45	    })();
46	    return () => {
47	      cancelled = true;
48	    };
49	  }, []);
50	
51	  if (!items || items.length === 0) return null;
52	
53	  const onRemove = (target: ContinueReadingItem) => {
54	    // Optimistic — pull the card out of the rendered list now; if
55	    // the DELETE fails the row will reappear on the next visit, but
56	    // a flash of "still there" is worse than a rare stale state.
57	    setItems((current) =>
58	      current
59	        ? current.filter(
60	            (item) =>
61	              !(
62	                item.contentType === target.contentType &&
63	                item.id === target.id
64	              ),
65	          )
66	        : current,
67	    );
68	    const sessionToken = getSessionToken();
69	    void deleteReadingPosition(
70	      target.contentType,
71	      target.id,
72	      sessionToken,
73	    ).catch(() => {
74	      // Swallow — see note above. A toast would be overkill for an
75	      // action the user can re-attempt at zero cost.
76	    });
77	  };
78	
79	  return (
80	    <section
81	      className={styles.section}
82	      aria-label="Pick up where you left off"
83	    >
84	      <header className={styles.header}>
85	        {/* h2 mirrors the heading level used by sibling homepage
86	            sections (ExpandableSection / ContinueReadingRow) — keeps
87	            the document outline flat at the section rank. */}
88	        <h2 className={styles.title}>Pick up where you left off</h2>
89	      </header>
90	      <ul className={styles.list}>
91	        {items.map((item) => (
92	          <li key={`${item.contentType}:${item.id}`}>
93	            <ContinueCard item={item} onRemove={() => onRemove(item)} />
94	          </li>
95	        ))}
96	      </ul>
97	    </section>
98	  );
99	}
100
